    rows = len(grid)
    cols = len(grid[0])

    # Identify background (most frequent) and foreground (second most)
    counts = {}
    for r in range(rows):
        for c in range(cols):
            counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1

    sorted_items = sorted(counts.items(), key=lambda x: x[1], reverse=True)
    bg_color = sorted_items[0][0]
    fg_color = sorted_items[1][0] if len(sorted_items) > 1 else 1

    # Copy the grid for output
    output = [row[:] for row in grid]

    # Forward ray-casting per row and column
    # For each direction, fill only up to the next non-background cell

    # Horizontal fill from each foreground pixel
    for r in range(rows):
        col_list = [(c, output[r][c]) for c in range(cols)]
        # Scan left to right, find foreground then fill to next foreground
        left_idx = 0
        for i, (c, val) in enumerate(col_list):
            if val == fg_color:
                # Fill all background pixels between this prominent and the next one
                while left_idx < i:
                    left_col, _ = col_list[left_idx]
                    if output[r][left_col] == fg_color and left_idx != i:
                        # Fill between left_col and current col
                        for j in range(left_col + 1, c):
                            if output[r][j] == bg_color:
                                output[r][j] = 2
                    left_idx += 1

    # Vertical fill using the same logic on columns
    for c in range(cols):
        row_col_list = [(r, output[r][c]) for r in range(rows)]
        top_idx = 0
        for i, (r, val) in enumerate(row_col_list):
